    type int8_kernel_t is array (0 to 8) of integer range -128 to 127;

    -- FOLDED (BatchNorm-absorbed) INT8 weights, kernel 0
    constant K0_FOLDED_CH0_W : int8_kernel_t := (110, 117, -38, 127, -28, 33, -66, 86, 124);
    constant K0_FOLDED_CH1_W : int8_kernel_t := (-103, 120, 24, 102, 20, 67, -19, 108, 20);
    constant K0_FOLDED_CH2_W : int8_kernel_t := (-68, 31, -72, -21, -59, 92, -112, -66, -44);

    -- Fixed-point Q.16 constants
    constant FRAC_BITS : integer := 16;
    constant SCALE_FX  : integer := 135;   -- unsigned, Q.16
    constant BIAS_FX   : integer := -936;   -- signed,   Q.16

    -- 9 Q.16 fixed-point expected outputs (row-major, output_index 0..8),
